const player=document.querySelector('#player'),video=player.querySelector('video');
function play(item){document.querySelector('#video-title').textContent=item.title;document.querySelector('#play-error').hidden=true;document.querySelector('#direct-video').href=item.file;video.src=item.file;video.poster=item.poster;player.showModal();video.play().catch(()=>{});}
player.querySelector('.modal-close').onclick=()=>player.close();player.addEventListener('close',()=>{video.pause();video.removeAttribute('src');video.load();});video.onerror=()=>document.querySelector('#play-error').hidden=false;
player.onclick=e=>{if(e.target===player)player.close();};
const duration=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
function card(item,cls='media-tile'){const b=document.createElement('button');b.className=cls;b.innerHTML=`<img src="${item.poster}" alt="" loading="lazy"><span class="play-mark">▶</span><span class="tile-caption"><b>${item.title}</b><small>${duration(item.duration)}</small></span>`;b.setAttribute('aria-label',`播放 ${item.title}`);b.onclick=()=>play(item);return b;}
fetch('media/videos.json').then(r=>{if(!r.ok)throw Error('目录未加载');return r.json()}).then(items=>{
document.querySelectorAll('[data-group]').forEach(g=>items.filter(i=>i.group===g.dataset.group).forEach(i=>g.append(card(i))));
items.filter(i=>i.group==='ai').forEach(i=>document.querySelector('#ai-cards').append(card(i,'ai-card')));
let center=0;const cards=[...document.querySelectorAll('.ai-card')];function render(){cards.forEach((c,i)=>{let o=(i-center+cards.length)%cards.length;if(o>1)o-=cards.length;c.style.transform=`translateX(${o*64}%) scale(${1-Math.abs(o)*.14}) rotateY(${-o*8}deg)`;c.style.zIndex=10-Math.abs(o);c.style.opacity=1-Math.abs(o)*.18;c.classList.toggle('active',i===center);});document.querySelector('#slide-count').textContent=`${center+1} / ${cards.length}`;}
document.querySelector('.prev').onclick=()=>{center=(center-1+cards.length)%cards.length;render()};document.querySelector('.next').onclick=()=>{center=(center+1)%cards.length;render()};render();
items.filter(i=>i.group==='ai').forEach((i,n)=>{const b=card(i,'stack-preview');b.style.transform=`translateX(${(n-1.5)*72}px) rotate(${(n-1.5)*7}deg)`;document.querySelector('#preview-stack').append(b);const img=document.createElement('img');img.src=i.poster;img.alt=i.title;img.loading='lazy';img.className=`scrap p${n+1}`;document.querySelector('#contact-posters').append(img);});
}).catch(()=>{document.querySelector('.title p').textContent='作品加载失败，请刷新页面重试。'});
const links=[...document.querySelectorAll('.nav-links a')];const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-20% 0px -55%'});links.forEach(a=>io.observe(document.querySelector(a.hash)));
const lb=document.querySelector('#lightbox');document.querySelector('.zoomable').onclick=e=>{lb.querySelector('img').src=e.currentTarget.dataset.src;lb.showModal()};lb.querySelector('button').onclick=()=>lb.close();lb.onclick=e=>{if(e.target===lb)lb.close()};
